    "image": "https://cdnphoto.dantri.com.vn/9UaPwbZHTEYwy3QHHi2yGNen5oQ=/zoom/1200_630/2026/02/07/viet-nam-phan-ung-voi-phat-bieu-gay-tranh-cai-ve-phu-nu-tu-quan-chuc-han-quoc-cropped-1770434681178.jpg"
