    "image": "https://cdnphoto.dantri.com.vn/Jg8ilyvcCgOyx0EATgogoLpKIJo=/zoom/1200_630/2026/10/18/ong-nguyen-duy-ngoc-vi-tri-viec-lam-khong-dua-tren-so-bien-che-hien-co-cropped-1792323046081.jpg"
